import{_ as s,o as t,c as e,ag as i}from"./chunks/framework.7He2WLS4.js";const k=JSON.parse('{"title":"Storage & Database","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/storage.md","filePath":"configuration/storage.md","lastUpdated":1772297611000}'),n={name:"configuration/storage.md"};function l(o,a,r,p,d,h){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="storage-database" tabindex="-1">Storage &amp; Database <a class="header-anchor" href="#storage-database" aria-label="Permalink to &quot;Storage &amp; Database&quot;">​</a></h1><p>NectoProxy uses a local SQLite database to persist all captured traffic, rules, breakpoints, sessions, and settings. This page explains the storage architecture, how to manage your data, and how to back up or migrate between machines.</p><h2 id="data-directory" tabindex="-1">Data Directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data Directory&quot;">​</a></h2><p>All NectoProxy data lives in a single directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.nectoproxy/</span></span></code></pre></div><p>This directory is created automatically the first time NectoProxy starts. It resolves to:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Path</th></tr></thead><tbody><tr><td><strong>Linux</strong></td><td><code>/home/&lt;username&gt;/.nectoproxy/</code></td></tr><tr><td><strong>macOS</strong></td><td><code>/Users/&lt;username&gt;/.nectoproxy/</code></td></tr><tr><td><strong>Windows</strong></td><td><code>C:\\Users\\&lt;username&gt;\\.nectoproxy\\</code></td></tr></tbody></table><h3 id="directory-structure" tabindex="-1">Directory Structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory Structure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.nectoproxy/</span></span>
<span class="line"><span>  data.db            # SQLite database (all application data)</span></span>
<span class="line"><span>  certs/</span></span>
<span class="line"><span>    ca.key            # CA private key (PEM)</span></span>
<span class="line"><span>    ca.crt            # CA certificate (PEM)</span></span>
<span class="line"><span>    &lt;domain&gt;.key      # Cached domain private keys</span></span>
<span class="line"><span>    &lt;domain&gt;.crt      # Cached domain certificates</span></span></code></pre></div><h2 id="database-file" tabindex="-1">Database File <a class="header-anchor" href="#database-file" aria-label="Permalink to &quot;Database File&quot;">​</a></h2><p>The database file is <code>data.db</code>, located at <code>~/.nectoproxy/data.db</code>. It is a standard SQLite 3 database using WAL (Write-Ahead Logging) mode for better concurrent read/write performance.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can inspect the database with any SQLite client:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span></span></code></pre></div></div><h3 id="database-tables" tabindex="-1">Database Tables <a class="header-anchor" href="#database-tables" aria-label="Permalink to &quot;Database Tables&quot;">​</a></h3><p>NectoProxy&#39;s database schema contains the following tables:</p><table tabindex="0"><thead><tr><th>Table</th><th>Purpose</th></tr></thead><tbody><tr><td><code>sessions</code></td><td>Capture sessions. Each session groups related traffic entries together.</td></tr><tr><td><code>traffic</code></td><td>HTTP/HTTPS request-response pairs. Contains method, URL, headers, bodies, status codes, timing data, and metadata flags.</td></tr><tr><td><code>rules</code></td><td>Rewrite rules (mock, block, delay, throttle, map-remote, map-local, modify-request, modify-response).</td></tr><tr><td><code>breakpoints</code></td><td>Breakpoint definitions for intercepting requests and responses.</td></tr><tr><td><code>ssl_passthrough</code></td><td>Domains that bypass MITM interception and pass through the proxy without decryption.</td></tr><tr><td><code>dns_mappings</code></td><td>Custom DNS mappings that override hostname resolution.</td></tr><tr><td><code>settings</code></td><td>Key-value store for application settings.</td></tr><tr><td><code>ws_frames</code></td><td>Individual WebSocket frames (direction, opcode, data, timestamp) linked to a parent traffic entry.</td></tr><tr><td><code>annotations</code></td><td>User-created notes and tags attached to individual traffic entries.</td></tr></tbody></table><h3 id="key-indexes" tabindex="-1">Key Indexes <a class="header-anchor" href="#key-indexes" aria-label="Permalink to &quot;Key Indexes&quot;">​</a></h3><p>The database includes indexes on frequently queried columns for fast lookups:</p><ul><li><code>idx_traffic_session</code> -- Traffic entries by session ID</li><li><code>idx_traffic_timestamp</code> -- Traffic entries by capture time</li><li><code>idx_traffic_host</code> -- Traffic entries by host/domain</li><li><code>idx_traffic_method</code> -- Traffic entries by HTTP method</li><li><code>idx_traffic_status</code> -- Traffic entries by response status code</li><li><code>idx_ws_frames_traffic</code> -- WebSocket frames by parent traffic entry</li><li><code>idx_annotations_traffic</code> -- Annotations by parent traffic entry</li></ul><h2 id="certificate-storage" tabindex="-1">Certificate Storage <a class="header-anchor" href="#certificate-storage" aria-label="Permalink to &quot;Certificate Storage&quot;">​</a></h2><p>The <code>certs/</code> subdirectory contains the Certificate Authority (CA) key pair and cached domain certificates:</p><table tabindex="0"><thead><tr><th>File</th><th>Description</th></tr></thead><tbody><tr><td><code>ca.key</code></td><td>The CA private key used to sign domain certificates. Keep this secure.</td></tr><tr><td><code>ca.crt</code></td><td>The CA certificate. This is the file you install in browsers and on devices.</td></tr><tr><td><code>*.key</code> / <code>*.crt</code></td><td>Cached per-domain certificates generated on-the-fly during HTTPS interception.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>The <code>ca.key</code> file is a private key. Anyone who has this file can generate certificates that your browser will trust (if you have installed the CA). Do not share it or commit it to version control.</p></div><h2 id="backing-up" tabindex="-1">Backing Up <a class="header-anchor" href="#backing-up" aria-label="Permalink to &quot;Backing Up&quot;">​</a></h2><p>Backing up NectoProxy is straightforward -- copy the data directory:</p><h3 id="full-backup" tabindex="-1">Full Backup <a class="header-anchor" href="#full-backup" aria-label="Permalink to &quot;Full Backup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop NectoProxy first (recommended to avoid WAL checkpoint issues)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Then copy the entire data directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/nectoproxy-backup-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span></span></code></pre></div><h3 id="database-only-backup" tabindex="-1">Database-Only Backup <a class="header-anchor" href="#database-only-backup" aria-label="Permalink to &quot;Database-Only Backup&quot;">​</a></h3><p>If you only need the traffic data, rules, and settings (not the certificates):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy just the database file and WAL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/nectoproxy-backup.db</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db-wal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/nectoproxy-backup.db-wal</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db-shm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/nectoproxy-backup.db-shm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>For a consistent backup, stop NectoProxy before copying the database file. If the proxy is running while you copy, the WAL file (<code>data.db-wal</code>) may be in an intermediate state. SQLite&#39;s WAL mode is crash-safe, but copying a partial WAL may result in a backup that is missing the most recent writes.</p></div><h2 id="restoring" tabindex="-1">Restoring <a class="header-anchor" href="#restoring" aria-label="Permalink to &quot;Restoring&quot;">​</a></h2><p>To restore from a backup:</p><ol><li>Stop NectoProxy if it is running.</li><li>Replace the data directory (or just the database file) with the backup.</li><li>Start NectoProxy.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop NectoProxy (Ctrl+C or kill the process)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restore full backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/nectoproxy-backup-20250228/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start NectoProxy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you only restore the database file without the <code>certs/</code> directory, NectoProxy will regenerate a new CA certificate on next launch. You will need to reinstall the CA certificate in your browsers and devices.</p></div><h2 id="database-size-management" tabindex="-1">Database Size Management <a class="header-anchor" href="#database-size-management" aria-label="Permalink to &quot;Database Size Management&quot;">​</a></h2><p>Over time, the database can grow large as traffic data accumulates. Here are strategies to keep it manageable:</p><h3 id="delete-old-sessions" tabindex="-1">Delete Old Sessions <a class="header-anchor" href="#delete-old-sessions" aria-label="Permalink to &quot;Delete Old Sessions&quot;">​</a></h3><p>The most effective way to reduce database size is to delete sessions you no longer need. Each session cascades deletes to all associated traffic entries, WebSocket frames, and annotations.</p><p><strong>Via the Web UI:</strong></p><ul><li>Open the Sessions panel</li><li>Click the delete button next to sessions you want to remove</li></ul><p><strong>Via the CLI:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List all sessions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete a specific session by ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><strong>Via the API:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/sessions/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="check-database-size" tabindex="-1">Check Database Size <a class="header-anchor" href="#check-database-size" aria-label="Permalink to &quot;Check Database Size&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check file size</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check table sizes inside SQLite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  SELECT &#39;traffic&#39; as tbl, count(*) as rows FROM traffic</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  UNION ALL</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  SELECT &#39;ws_frames&#39;, count(*) FROM ws_frames</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  UNION ALL</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  SELECT &#39;sessions&#39;, count(*) FROM sessions</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  UNION ALL</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  SELECT &#39;annotations&#39;, count(*) FROM annotations;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h3 id="compact-the-database" tabindex="-1">Compact the Database <a class="header-anchor" href="#compact-the-database" aria-label="Permalink to &quot;Compact the Database&quot;">​</a></h3><p>After deleting large amounts of data, SQLite may not immediately reclaim disk space. Run <code>VACUUM</code> to compact:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/data.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;VACUUM;&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>VACUUM</code> temporarily requires up to 2x the current database size in free disk space, as it creates a copy of the database. Make sure you have enough disk space before running it.</p></div><h2 id="migrating-between-machines" tabindex="-1">Migrating Between Machines <a class="header-anchor" href="#migrating-between-machines" aria-label="Permalink to &quot;Migrating Between Machines&quot;">​</a></h2><p>To move NectoProxy data to another machine:</p><ol><li><strong>Stop NectoProxy</strong> on the source machine.</li><li><strong>Copy the entire <code>~/.nectoproxy/</code> directory</strong> to the target machine:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On source machine</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> czf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy-data.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Transfer to target machine (e.g., via scp)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy-data.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@target-machine:~/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On target machine</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy-data.tar.gz</span></span></code></pre></div><ol start="3"><li><strong>Install NectoProxy</strong> on the target machine if not already installed.</li><li><strong>Start NectoProxy</strong>. All sessions, traffic, rules, and settings will be available.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you migrate the <code>certs/</code> directory along with the database, the CA certificate remains the same. Devices that already trust the old CA will continue to work without reinstalling certificates. If you only migrate the database, a new CA will be generated and you will need to distribute the new certificate.</p></div><details class="details custom-block"><summary>Can I Use an External SQLite Viewer?</summary><p>Yes. The <code>data.db</code> file is a standard SQLite 3 database. You can open it with any tool that supports SQLite, such as <a href="https://sqlitebrowser.org/" target="_blank" rel="noreferrer">DB Browser for SQLite</a>, the <code>sqlite3</code> CLI, or DBeaver. Close NectoProxy first, or open the database in read-only mode to avoid locking conflicts.</p></details>`,58)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
